/// a curve at the contraction h; outside its ends continued linearly with the end segment
inline double curveAt(const std::vector<Point> &c, double h)
{
	std::size_t i = 1;
	if (h >= c.back().h) i = c.size() - 1;
	else if (h > c.front().h)
		while (i + 1 < c.size() && c[i].h < h) ++i;
	const Point &a = c[i - 1], &b = c[i];
	return b.h != a.h ? a.f + (b.f - a.f) * (h - a.h) / (b.h - a.h) : a.f;
}

/// tensile force [N] at the contraction h [%] and the gauge pressure bar: linear between the curves of
/// neighbouring pressures, above the highest curve continued linearly, below 0 bar the 0-bar curve
inline double force(const Type &t, double h, double bar)
{
	const int n = static_cast<int>(t.curves.size()) - 1;
	const double b = std::max(bar, 0.0);
	const int i = std::min(static_cast<int>(std::floor(b)), n - 1);
	const double f0 = curveAt(t.curves[i], h), f1 = curveAt(t.curves[i + 1], h);
	return f0 + (f1 - f0) * (b - i);
}

/// effective area dF/dp [m²] at the contraction h: least squares slope over all pressure curves
inline double area(const Type &t, double h)
{
	const int n = static_cast<int>(t.curves.size());
	double mp = 0, mf = 0;
	std::vector<double> f(n);
	for (int i = 0; i < n; ++i) { f[i] = curveAt(t.curves[i], h); mp += i; mf += f[i]; }
	mp /= n; mf /= n;
	double sxy = 0, sxx = 0;
	for (int i = 0; i < n; ++i) { sxy += (i - mp) * (f[i] - mf); sxx += (i - mp) * (i - mp); }
	return sxy / sxx / 1e5;
}

/// volume per metre nominal length [m³/m] at the contraction h by virtual work: V = π/4·I.D.² + ∫₀^h A dh
inline double volumePerMetre(const Type &t, double h)
{
	const int n = std::max(1, static_cast<int>(std::ceil(std::abs(h) / 0.05)));
	double v = M_PI / 4 * t.id * t.id, a0 = area(t, 0.0);
	for (int i = 1; i <= n; ++i) {
		const double a1 = area(t, h * i / n);
		v += 0.5 * (a0 + a1) * (h / n) / 100.0;
		a0 = a1;
	}
	return v;
}

